`timescale 1ns/1ps

module sgdma_ip#(
    parameter DLY               = 1,
    parameter CWC_DBG           = 0,

    parameter DEVICE_FAMILY     = "PH1A",//"PH1A",PH2A,PH1P,DR1
    parameter DATA_WIDTH        = ( DEVICE_FAMILY == "PH1A100")? 64 : 
                                  ((DEVICE_FAMILY == "PH1A")   ? 128:
                                  ((DEVICE_FAMILY == "PH1P")   ? 256: 512)),
    parameter DATA_BYTE         = DATA_WIDTH/8,
    parameter DATA_DW           = DATA_WIDTH/32, 
    parameter NBYTE_WIDTH       = $clog2(DATA_BYTE),
    parameter NDW_WIDTH         = $clog2(DATA_DW), 
    //AXI user signal width
    parameter RQ_TUSER_WIDTH    = 62,
    parameter RC_TUSER_WIDTH    = 75,
    parameter CQ_TUSER_WIDTH    = 88,
    parameter CC_TUSER_WIDTH    = 33,    
    //
    parameter AXI4MM_BUS_EN     = 0,
    parameter AXI4ST_BUS_EN     = 1,
    parameter DMA_BYPA_EN       = 0,    
    parameter PAR_CHK           = 0,
    parameter PAR_PROP          = 0,
    parameter PAR_CHK_EN        = (PAR_CHK !=0) || (PAR_PROP != 0) ,
    //Set config interface
    parameter AXI4L_MBUS_EN     = 1,
    parameter AXI4L_SBUS_EN     = 1,
    //set interrupt type
    parameter LGCY_EN           = 0,
    parameter MSI_EN            = 0,
    parameter MSIX_EN           = 0,
    //Config channels of DMA
    parameter H2C_CHNL_NUM      = 4,
    parameter H2C_DSC_BYP_MAP   = {H2C_CHNL_NUM{1'b0}},
    parameter C2H_CHNL_NUM      = 4,
    parameter C2H_DSC_BYP_MAP   = {C2H_CHNL_NUM{1'b0}},
    parameter DMA_USR_IRQ       = 1,

    parameter H2C_ID_NUM        = 32,
    parameter H2C_STRT_ID       = 0,
    parameter C2H_STRT_ID       = H2C_ID_NUM,
    parameter C2H_ID_NUM        = 16,
    //calculate RX BUFFER size
    //Support MAX MRRS is 512Bytes
    parameter RXBUF_SIZE        = H2C_ID_NUM*512*2,  
    //
    parameter DMA_BAR           = 1,    
    parameter AXI4LITE_BAR      = 0,
    //---Stream select 1: AXI4-Stream Interface,0: AXI4 Memory Mapped Interface---
    // parameter DATA_WIDTH        = 64,
    // parameter DATA_BYTE         = DATA_WIDTH/8,
    parameter AXI4MM_BRSTD_LEN  = 16,
    parameter AXI4MM_BL_WD      = 4
    )(
    input   wire                                    core_rstn,
    input   wire                                    core_clk,
    output  wire    [7:0]                           c2h_sts_0_o,
    output  wire    [7:0]                           h2c_sts_0_o,
    output  wire    [7:0]                           c2h_sts_1_o,
    output  wire    [7:0]                           h2c_sts_1_o,
    output  wire    [7:0]                           c2h_sts_2_o,
    output  wire    [7:0]                           h2c_sts_2_o,
    output  wire    [7:0]                           c2h_sts_3_o,
    output  wire    [7:0]                           h2c_sts_3_o,
    //cfg direct access interface---
    input   wire    [12:0]                          tl_cfg_busdev_i,
    input   wire    [2:0]                           tl_cfg_max_payload_size_i,
    input   wire    [2:0]                           tl_cfg_max_read_request_size_i,           
    //---IRQ interface-------------------------------//
    // legacy int not support now
    output  wire    [3:0]                           cfg_interrupt_int,                           
    output  wire    [3:0]                           cfg_interrupt_pending ,                      
    input   wire                                    cfg_interrupt_sent ,                         
    // msi signals                      
    input   wire    [3:0]                           cfg_interrupt_msi_enable  ,                  
    input   wire    [11:0]                          cfg_interrupt_msi_mmenable ,    // not support at this time, user need read pcie register self
    input   wire                                    cfg_interrupt_msi_mask_update,   // not support 
    input   wire    [31:0]                          cfg_interrupt_msi_data,                            
    output  wire    [1:0]                           cfg_interrupt_msi_select,                
    output  wire    [31:0]                          cfg_interrupt_msi_int,                   
    output  wire    [31:0]                          cfg_interrupt_msi_pending_status  ,          
    output  wire                                    cfg_interrupt_msi_pending_status_data_enable,
    output  wire    [1:0]                           cfg_interrupt_msi_pending_status_function_num,
    input   wire                                    cfg_interrupt_msi_sent ,                     
    input   wire                                    cfg_interrupt_msi_fail ,                     
    output  wire    [2:0]                           cfg_interrupt_msi_attr ,                     
    output  wire                                    cfg_interrupt_msi_tph_present  ,             
    output  wire    [1:0]                           cfg_interrupt_msi_tph_type ,                 
    output  wire    [7:0]                           cfg_interrupt_msi_tph_st_tag ,               
    output  wire    [7:0]                           cfg_interrupt_msi_function_number  ,   
    //user mgmt port
    input   wire    [18:0]                          cfg_mgmt_addr_i,
    input   wire                                    cfg_mgmt_write_i,
    input   wire    [31:0]                          cfg_mgmt_write_data_i,
    input   wire    [3:0]                           cfg_mgmt_byte_enable_i,
    input   wire                                    cfg_mgmt_read_i,
    output  wire    [31:0]                          cfg_mgmt_read_data_o,
    output  wire                                    cfg_mgmt_read_write_done_o,
    input   wire                                    cfg_mgmt_type1_cfg_reg_access_i,  
    //to bridge
    output  wire    [18:0]                          cfg_mgmt_addr_o,
    output  wire                                    cfg_mgmt_write_o,
    output  wire    [31:0]                          cfg_mgmt_write_data_o,
    output  wire    [3:0]                           cfg_mgmt_byte_enable_o,
    output  wire                                    cfg_mgmt_read_o,
    input   wire    [31:0]                          cfg_mgmt_read_data_i,
    input   wire                                    cfg_mgmt_read_write_done_i,
    output  wire                                    cfg_mgmt_type1_cfg_reg_access_o,  
    //*************************************************************//
    //***************************USER INTERFACE********************//
    //*************************************************************//
    input   wire    [3:0]                           tl_cfg_msix_enable_i,
    input   wire    [3:0]                           tl_cfg_msix_function_mask_i,
    
    input   wire    [DMA_USR_IRQ-1:0]               usr_irq_req_i,
    output  wire    [DMA_USR_IRQ-1:0]               usr_irq_ack_o,
    output  wire                                    legacy_enable_o,
    output  wire    [2:0]                           legacy_vector_width_o,
    output  wire                                    msi_enable_o,
    output  wire    [2:0]                           msi_vector_width_o,
    output  wire                                    msix_enable_o,
    output  wire    [4:0]                           msix_vector_width_o,    
    //CQ
    input   wire    [DATA_WIDTH-1:0]                m_axis_cq_tdata_i, 
    input   wire    [DATA_DW-1:0]                   m_axis_cq_tkeep_i, 
    input   wire    [CQ_TUSER_WIDTH-1:0]            m_axis_cq_tuser_i,     
    input   wire                                    m_axis_cq_tvalid_i, 
    input   wire                                    m_axis_cq_tlast_i, 
    output  wire                                    m_axis_cq_tready_o, 
    //CC               
    output  wire    [DATA_WIDTH-1:0]                m_axis_cc_tdata_o, 
    output  wire    [DATA_DW-1:0]                   m_axis_cc_tkeep_o, 
    output  wire    [CC_TUSER_WIDTH-1:0]            m_axis_cc_tuser_o,     
    output  wire                                    m_axis_cc_tvalid_o, 
    output  wire                                    m_axis_cc_tlast_o, 
    input   wire                                    m_axis_cc_tready_i,    
    //RQ               
    output  wire    [DATA_WIDTH-1:0]                m_axis_rq_tdata_o, 
    output  wire    [DATA_DW-1:0]                   m_axis_rq_tkeep_o, 
    output  wire    [RQ_TUSER_WIDTH-1:0]            m_axis_rq_tuser_o,     
    output  wire                                    m_axis_rq_tvalid_o, 
    output  wire                                    m_axis_rq_tlast_o, 
    input   wire                                    m_axis_rq_tready_i,  
    input   wire    [4:0]                           tuser2rq_i,
    //RC              
    input   wire    [DATA_WIDTH-1:0]                m_axis_rc_tdata_i, 
    input   wire    [DATA_DW-1:0]                   m_axis_rc_tkeep_i, 
    input   wire    [RC_TUSER_WIDTH-1:0]            m_axis_rc_tuser_i,     
    input   wire                                    m_axis_rc_tvalid_i, 
    input   wire                                    m_axis_rc_tlast_i, 
    output  wire                                    m_axis_rc_tready_o,     
    //AXI4-LITE Master interface
    output  wire    [31:0]                          m_axil_awaddr_o,
    output  wire    [2:0]                           m_axil_awprot_o,
    output  wire                                    m_axil_awvalid_o,
    input   wire                                    m_axil_awready_i,
    output  wire    [31:0]                          m_axil_wdata_o,
    output  wire    [3:0]                           m_axil_wstrb_o,
    output  wire                                    m_axil_wvalid_o,
    input   wire                                    m_axil_wready_i,
    input   wire                                    m_axil_bvalid_i,
    input   wire    [1:0]                           m_axil_bresp_i,
    output  wire                                    m_axil_bready_o,
    output  wire    [31:0]                          m_axil_araddr_o,
    output  wire    [2:0]                           m_axil_arprot_o,
    output  wire                                    m_axil_arvalid_o,
    input   wire                                    m_axil_arready_i,
    input   wire    [31:0]                          m_axil_rdata_i,
    input   wire    [1:0]                           m_axil_rresp_i,
    input   wire                                    m_axil_rvalid_i,
    output  wire                                    m_axil_rready_o,
    //AXI4-LITE Slave interface
    input   wire    [31:0]                          s_axil_awaddr_i,
    input   wire    [2:0]                           s_axil_awprot_i,
    input   wire                                    s_axil_awvalid_i,
    output  wire                                    s_axil_awready_o,
    input   wire    [31:0]                          s_axil_wdata_i,
    input   wire    [3:0]                           s_axil_wstrb_i,
    input   wire                                    s_axil_wvalid_i,
    output  wire                                    s_axil_wready_o,
    output  wire                                    s_axil_bvalid_o,
    output  wire    [1:0]                           s_axil_bresp_o,
    input   wire                                    s_axil_bready_i,
    input   wire    [31:0]                          s_axil_araddr_i,
    input   wire    [2:0]                           s_axil_arprot_i,
    input   wire                                    s_axil_arvalid_i,
    output  wire                                    s_axil_arready_o,
    output  wire    [31:0]                          s_axil_rdata_o,
    output  wire    [1:0]                           s_axil_rresp_o,
    output  wire                                    s_axil_rvalid_o,
    input   wire                                    s_axil_rready_i,

    output  wire    [C2H_CHNL_NUM-1:0]              s_axis_tx_rst_o,
    output  wire    [H2C_CHNL_NUM-1:0]              m_axis_rx_rst_o,
    output  wire                                    s_axis_tx_run_o,
    output  wire                                    m_axis_rx_run_o,
// `ifdef DMA_BYPA_EN
    input   wire                                    m_axib_arready_i,
    output  wire    [3:0]                           m_axib_arid_o,
    output  wire    [63:0]                          m_axib_araddr_o,
    output  wire    [7:0]                           m_axib_arlen_o,
    output  wire    [2:0]                           m_axib_arsize_o,
    output  wire    [1:0]                           m_axib_arburst_o,
    output  wire    [2:0]                           m_axib_arprot_o,
    output  wire                                    m_axib_arvalid_o,
    output  wire                                    m_axib_arlock_o,
    output  wire    [3:0]                           m_axib_arcache_o,
    input   wire    [3:0]                           m_axib_rid_i,
    input   wire    [DATA_WIDTH-1:0]                m_axib_rdata_i,
    input   wire    [1:0]                           m_axib_rresp_i,
    input   wire                                    m_axib_rlast_i,
    input   wire                                    m_axib_rvalid_i,
    output  wire                                    m_axib_rready_o,
                        
    input   wire                                    m_axib_awready_i,
    output  wire    [3:0]                           m_axib_awid_o,
    output  wire    [63:0]                          m_axib_awaddr_o,
    output  wire    [7:0]                           m_axib_awlen_o,
    output  wire    [2:0]                           m_axib_awsize_o,
    output  wire    [1:0]                           m_axib_awburst_o,
    output  wire    [2:0]                           m_axib_awprot_o,
    output  wire                                    m_axib_awvalid_o,
    output  wire                                    m_axib_awlock_o,
    output  wire    [3:0]                           m_axib_awcache_o,
    output  wire    [DATA_WIDTH:0]                  m_axib_wdata_o,
    output  wire    [DATA_BYTE-1:0]                 m_axib_wstrb_o,
    input   wire                                    m_axib_wready_i,
    output  wire                                    m_axib_wlast_o,
    output  wire                                    m_axib_wvalid_o,
    input   wire    [3:0]                           m_axib_bid_i,
    input   wire    [1:0]                           m_axib_bresp_i,
    input   wire                                    m_axib_bvalid_i,
    output  wire                                    m_axib_bready_o,
    //AXI ST interface
    output  wire    [C2H_CHNL_NUM-1:0]              s_axis_tx_tready_o,
    input   wire    [DATA_WIDTH*C2H_CHNL_NUM-1:0]   s_axis_tx_tdata_i,
    input   wire    [DATA_BYTE*C2H_CHNL_NUM-1:0]    s_axis_tx_tkeep_i,
    input   wire    [DATA_BYTE*C2H_CHNL_NUM-1:0]    s_axis_tx_tuser_i,
    input   wire    [C2H_CHNL_NUM-1:0]              s_axis_tx_tlast_i,
    input   wire    [C2H_CHNL_NUM-1:0]              s_axis_tx_tvalid_i,

    input   wire    [H2C_CHNL_NUM-1:0]              m_axis_rx_tready_i,
    output  wire    [DATA_WIDTH*H2C_CHNL_NUM-1:0]   m_axis_rx_tdata_o,
    output  wire    [DATA_BYTE*H2C_CHNL_NUM-1:0]    m_axis_rx_tkeep_o,
    output  wire    [DATA_BYTE*H2C_CHNL_NUM-1:0]    m_axis_rx_tuser_o,
    output  wire    [H2C_CHNL_NUM-1:0]              m_axis_rx_tlast_o,
    output  wire    [H2C_CHNL_NUM-1:0]              m_axis_rx_tvalid_o,
    // AXI MM interface
    input   wire                                    m_axi_arready_i,
    output  wire    [3:0]                           m_axi_arid_o,
    output  wire    [63:0]                          m_axi_araddr_o,
    output  wire    [7:0]                           m_axi_arlen_o,
    output  wire    [2:0]                           m_axi_arsize_o,
    output  wire    [1:0]                           m_axi_arburst_o,
    output  wire    [2:0]                           m_axi_arprot_o,
    output  wire                                    m_axi_arvalid_o,
    output  wire                                    m_axi_arlock_o,
    output  wire    [3:0]                           m_axi_arcache_o,                
    input   wire    [3:0]                           m_axi_rid_i,
    input   wire    [DATA_WIDTH-1:0]                m_axi_rdata_i,
    input   wire    [DATA_BYTE-1:0]                 m_axi_ruser_i,
    input   wire    [1:0]                           m_axi_rresp_i,
    input   wire                                    m_axi_rlast_i,
    input   wire                                    m_axi_rvalid_i,
    output  wire                                    m_axi_rready_o,
                        
    input   wire                                    m_axi_awready_i,
    output  wire    [3:0]                           m_axi_awid_o,
    output  wire    [63:0]                          m_axi_awaddr_o,
    output  wire    [7:0]                           m_axi_awlen_o,
    output  wire    [2:0]                           m_axi_awsize_o,
    output  wire    [1:0]                           m_axi_awburst_o,
    output  wire    [2:0]                           m_axi_awprot_o,
    output  wire                                    m_axi_awvalid_o,
    output  wire                                    m_axi_awlock_o,
    output  wire    [3:0]                           m_axi_awcache_o,
    output  wire    [DATA_WIDTH-1:0]                m_axi_wdata_o,
    output  wire    [DATA_BYTE-1:0]                 m_axi_wstrb_o,
    input   wire                                    m_axi_wready_i,
    output  wire                                    m_axi_wlast_o,
    output  wire                                    m_axi_wvalid_o,
    input   wire    [3:0]                           m_axi_bid_i,
    input   wire    [1:0]                           m_axi_bresp_i,
    input   wire                                    m_axi_bvalid_i,
    output  wire                                    m_axi_bready_o,

    //Descriptor byapss interface
    output  wire                                    c2h_dsc_byp_ready_0_o,
    input   wire                                    c2h_dsc_byp_load_0_i,
    input   wire    [63:0]                          c2h_dsc_byp_src_addr_0_i,
    input   wire    [63:0]                          c2h_dsc_byp_dst_addr_0_i,
    input   wire    [27:0]                          c2h_dsc_byp_len_0_i,
    input   wire    [15:0]                          c2h_dsc_byp_ctl_0_i,
                        
    output  wire                                    c2h_dsc_byp_ready_1_o,
    input   wire                                    c2h_dsc_byp_load_1_i,
    input   wire    [63:0]                          c2h_dsc_byp_src_addr_1_i,
    input   wire    [63:0]                          c2h_dsc_byp_dst_addr_1_i,
    input   wire    [27:0]                          c2h_dsc_byp_len_1_i,
    input   wire    [15:0]                          c2h_dsc_byp_ctl_1_i,
                        
    output  wire                                    c2h_dsc_byp_ready_2_o,
    input   wire                                    c2h_dsc_byp_load_2_i,
    input   wire    [63:0]                          c2h_dsc_byp_src_addr_2_i,
    input   wire    [63:0]                          c2h_dsc_byp_dst_addr_2_i,
    input   wire    [27:0]                          c2h_dsc_byp_len_2_i,
    input   wire    [15:0]                          c2h_dsc_byp_ctl_2_i,
                        
    output  wire                                    c2h_dsc_byp_ready_3_o,
    input   wire                                    c2h_dsc_byp_load_3_i,
    input   wire    [63:0]                          c2h_dsc_byp_src_addr_3_i,
    input   wire    [63:0]                          c2h_dsc_byp_dst_addr_3_i,
    input   wire    [27:0]                          c2h_dsc_byp_len_3_i,
    input   wire    [15:0]                          c2h_dsc_byp_ctl_3_i,
                        
    output  wire                                    h2c_dsc_byp_ready_0_o,
    input   wire                                    h2c_dsc_byp_load_0_i,
    input   wire    [63:0]                          h2c_dsc_byp_src_addr_0_i,
    input   wire    [63:0]                          h2c_dsc_byp_dst_addr_0_i,
    input   wire    [27:0]                          h2c_dsc_byp_len_0_i,
    input   wire    [15:0]                          h2c_dsc_byp_ctl_0_i,
                        
    output  wire                                    h2c_dsc_byp_ready_1_o,
    input   wire                                    h2c_dsc_byp_load_1_i,
    input   wire    [63:0]                          h2c_dsc_byp_src_addr_1_i,
    input   wire    [63:0]                          h2c_dsc_byp_dst_addr_1_i,
    input   wire    [27:0]                          h2c_dsc_byp_len_1_i,
    input   wire    [15:0]                          h2c_dsc_byp_ctl_1_i,
                        
    output  wire                                    h2c_dsc_byp_ready_2_o,
    input   wire                                    h2c_dsc_byp_load_2_i,
    input   wire    [63:0]                          h2c_dsc_byp_src_addr_2_i,
    input   wire    [63:0]                          h2c_dsc_byp_dst_addr_2_i,
    input   wire    [27:0]                          h2c_dsc_byp_len_2_i,
    input   wire    [15:0]                          h2c_dsc_byp_ctl_2_i,
                        
    output  wire                                    h2c_dsc_byp_ready_3_o,
    input   wire                                    h2c_dsc_byp_load_3_i,
    input   wire    [63:0]                          h2c_dsc_byp_src_addr_3_i,
    input   wire    [63:0]                          h2c_dsc_byp_dst_addr_3_i,
    input   wire    [27:0]                          h2c_dsc_byp_len_3_i,
    input   wire    [15:0]                          h2c_dsc_byp_ctl_3_i
);
